SELECT	COUNT(*) AS CNT
FROM	UI_ID_NOLOG
WHERE	USER_ID		= #{userId}
AND		(

		FIND_IN_SET(#{svc}, SERVICECD)

)

	AND		ID_LOG_SEQ != #{idLogSeq}

mapper.update:
UPDATE	UI_ID_NOLOG
SET		SERVICECD 	= #{serviceCd},
USER_ID		= #{userId},
UPDATE_DT	= NOW(),
UPDATE_ID	= #{updateId}
WHERE	ID_LOG_SEQ	= #{idLogSeq}

mapper.select:
SELECT  	COUNT(*) AS CNT
FROM		UI_IP_NOLOG
WHERE		IP_LOG_SEQ != #{ipLogSeq}
AND		(
INET6_ATON(#{userSIp}) BETWEEN INET6_ATON(USER_S_IP)	AND	INET6_ATON(USER_E_IP)	OR	INET6_ATON(#{userEIp}) BETWEEN INET6_ATON(USER_S_IP) AND INET6_ATON(USER_E_IP) OR
INET6_ATON(USER_S_IP) BETWEEN INET6_ATON(#{userSIp})	AND	INET6_ATON(#{userEIp})	OR	INET6_ATON(USER_E_IP) BETWEEN INET6_ATON(#{userSIp}) AND INET6_ATON(#{userEIp})
)
AND		(
INET6_ATON(#{serverSIp})	BETWEEN	INET6_ATON(SERVER_S_IP)	AND	INET6_ATON(SERVER_E_IP)	OR	INET6_ATON(#{serverEIp})	BETWEEN INET6_ATON(SERVER_S_IP)	AND INET6_ATON(SERVER_E_IP) OR
INET6_ATON(SERVER_S_IP)	BETWEEN INET6_ATON(#{serverSIp}) AND INET6_ATON(#{serverEIp})	OR	INET6_ATON(SERVER_E_IP)	BETWEEN INET6_ATON(#{serverSIp})	AND INET6_ATON(#{serverEIp})
)
AND		(
#{userSPort}	BETWEEN USER_S_PORT	AND	USER_E_PORT OR #{userEPort} BETWEEN USER_S_PORT AND USER_E_PORT OR
USER_S_PORT BETWEEN #{userSPort} AND #{userEPort} OR USER_E_PORT BETWEEN #{userSPort} AND #{userEPort}
)
AND		(
#{serverSPort} BETWEEN SERVER_S_PORT AND SERVER_E_PORT OR #{serverEPort} BETWEEN SERVER_S_PORT AND SERVER_E_PORT OR
SERVER_S_PORT BETWEEN #{serverSPort} AND #{serverEPort} OR SERVER_E_PORT BETWEEN #{serverSPort} AND #{serverEPort}
)

