INSERT	INTO UI_ATTACH_NOLOG ( ATTACH_LOG_SEQ, SERVICECD, SUBJECT, CREATE_DT, USE_YN, CREATE_USER, UPDATE_DT, UPDATE_ID )
SELECT	IFNULL(MAX(CAST(ATTACH_LOG_SEQ AS UNSIGNED)),0)+1, #{serviceCd}, #{subject}, NOW(), 'Y', #{createId}, now(), #{updateId}
FROM	UI_ATTACH_NOLOG

mapper.update:
UPDATE	UI_ATTACH_NOLOG
SET		SERVICECD 	= #{serviceCd},
SUBJECT		= #{subject},
UPDATE_DT	= NOW(),
UPDATE_ID	= #{updateId}
WHERE	ATTACH_LOG_SEQ	= #{attachLogSeq}

